// kaiware007 + IkeC - Cyber Fuji 2020.0 / https://www.shadertoy.com/view/Wt33Wf
// Transpiled to HLSL using Milkwave
#define tx sin(uTime)*0.5+1
float mod_conv(float x, float y) { return x - y * floor(x / y); }
vec2 mod_conv(vec2 x, vec2 y) { return x - y * floor(x / y); }
vec3 mod_conv(vec3 x, vec3 y) { return x - y * floor(x / y); }
vec4 mod_conv(vec4 x, vec4 y) { return x - y * floor(x / y); }
float sun(vec2 uv_conv,  float battery)
{
float val = smoothstep(0.3, 0.29, length(uv_conv));
float bloom = smoothstep(0.7, 0.0, length(uv_conv));
float cut = 3.0 * sin((uv_conv.y + uTime * 0.2 * (battery + 0.02)) * 100.0)
+ clamp(uv_conv.y * 14.0 + 1.0, -6.0, 6.0);
cut = clamp(cut, 0.0, 1.0);
return clamp(val * cut, 0.0, 1.0) + bloom * 0.6;
}
float grid(vec2 uv_conv,  float battery)
{
vec2 size = vec2(uv_conv.y, uv_conv.y * uv_conv.y * 0.2) * 0.01;
uv_conv += vec2(0.0, uTime * 4.0 * (battery + 0.05));
uv_conv = abs(fract(uv_conv) - 0.5);
vec2 lines = smoothstep(size, vec2(0.0, 0.0), uv_conv);
lines += smoothstep(size * 5.0, vec2(0.0, 0.0), uv_conv) * 0.4 * battery;
return clamp(lines.x + lines.y, 0.0, 3.0);
}
float dot2(in vec2 v ) { return dot(v,v); }
float sdTrapezoid( in vec2 p, in float r1, float r2, float he )
{
vec2 k1 = vec2(r2,he);
vec2 k2 = vec2(r2-r1,2.0*he);
p.x = abs(p.x);
vec2 ca = vec2(p.x-min(p.x,(p.y<0.0)?r1:r2), abs(p.y)-he);
vec2 cb = p - k1 + k2*clamp( dot(k1-p,k2)/dot2(k2), 0.0, 1.0 );
float s = (cb.x<0.0 && ca.y<0.0) ? -1.0 : 1.0;
return s*sqrt( min(dot2(ca),dot2(cb)) );
}
float sdLine( in vec2 p, in vec2 a, in vec2 b )
{
vec2 pa = p-a, ba = b-a;
float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
return length( pa - ba*h );
}
float sdBox( in vec2 p, in vec2 b )
{
vec2 d = abs(p)-b;
return length(max(d,vec2( 0.0 , 0.0 ))) + min(max(d.x,d.y),0.0);
}
float opSmoothUnion(float d1, float d2, float k){
float h = clamp(0.5 + 0.5 * (d2 - d1) /k,0.0,1.0);
return mix(d2, d1 , h) - k * h * ( 1.0 - h);
}
float sdCloud(in vec2 p, in vec2 a1, in vec2 b1, in vec2 a2, in vec2 b2, float w)
{
// float lineVal1 = smoothstep(w - 0.0001, w, sdLine(p, a1, b1));
#ifdef bass_smooth
float fac = (int)vis_version > 2 ? 1.0 - vis_intensity+vis_shift : (1.0 - smoothstep( 0.0 , 2.0 ,(int)vis_version == 1 ? bass_smooth : audioLowSmooth)*0.2)*vis_intensity+vis_shift;
#else
float fac = 1.0 - smoothstep( 0.0 , 2.0 ,vol_att)*0.1;
#endif
float lineVal1 = fac*sdLine(p, a1, b1);
float lineVal2 = fac*sdLine(p, a2, b2);
vec2 ww = vec2(w*1.5, 0.0);
vec2 left = max(a1 + ww, a2 + ww);
vec2 right = min(b1 - ww, b2 - ww);
vec2 boxCenter = (left + right) * 0.5;
// float boxW = right.x - left.x;
float boxH = abs(a2.y - a1.y) * 0.5;
// float boxVal = sdBox(p - boxCenter, vec2(boxW, boxH)) + w;
float boxVal = sdBox(p - boxCenter, vec2(0.04, boxH)) + w;
float uniVal1 = opSmoothUnion(lineVal1, boxVal, 0.05);
float uniVal2 = opSmoothUnion(lineVal2, boxVal, 0.05);
return min(uniVal1, uniVal2);
}
else
{
float fujiD = min(uv.y * 4.5 - 0.5, 1.0);
uv.y -= battery * 1.1 - 0.51;
vec2 sunUV = uv;
vec2 fujiUV = uv;
// Sun
